function circleForm(x, y, d, p ) {

	let branch = int(random(500, 1000));
	let ang = TAU / branch;
	let angles = [];
	for (let i = 0; i < branch; i++) {
		angles.push(ang * (i + iteration(0.1, 0.25)));
	}
	for (let i = 0; i < branch; i++) {
		let ang1 = angles[i];
		let ang2 = angles[(i + int(random(6))) % angles.length];
		let dd = d * iteration(0.1, 1);
		p.noFill();
		p.drawingContext.shadowColor = random(colors3);
		p.drawingContext.shadowOffsetX = 1;
		p.drawingContext.shadowOffsetY = 1;
		p.drawingContext.shadowBlur = 0;
		p.stroke(random(colors3));

		p.strokeCap(SQUARE);
		p.strokeWeight(random(1));
		p.arc(x, y, dd, dd, ang1, ang2);
	}
	// if (frameCount == 6*25) noLoop();
}

function iteration(s, e) {
	let t = random(10, 100);
	let v = random(0.001, 0.01);
	return map(sin(t + frameCount * v), -1, 1, s, e);
}

